class Solution {
public:
    int numDecodings(string s) {
        int n = s.size();
        if (n == 0 || s[0] == '0') return 0;
        int prev2 = 1;          // dp[i-2]
        int prev  = 1;          // dp[i-1] for i = 1 (first character is non‑zero)
        for (int i = 1; i < n; ++i) {
            int cur = 0;
            if (s[i] != '0')               // single digit decode
                cur += prev;
            int two = (s[i-1] - '0') * 10 + (s[i] - '0');
            if (two >= 10 && two <= 26)    // two‑digit decode
                cur += prev2;
            prev2 = prev;
            prev  = cur;
            if (prev == 0) return 0;       // early exit if no ways so far
        }
        return prev;
    }
};
